import { test, expect } from '@playwright/test';

test.describe('Debounced Search Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should trigger search API only after 300ms pause in typing', async ({ page }) => {
    // Setup API interception
    await page.route('**/api/search?q=*', (route) => {
      route.continue();
    });

    // Get search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Get search button using getByRole
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();

    // Get results container using getByRole
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Intercept and count API calls
    let apiCallCount = 0;
    await page.route('**/api/search?q=*', (route) => {
      apiCallCount++;
      route.continue();
    });

    // Type first character
    await searchInput.fill('a');
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (less than 300ms)
    await page.waitForTimeout(100);

    // Type second character
    await searchInput.fill('ap');
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (less than 300ms)
    await page.waitForTimeout(100);

    // Type third character
    await searchInput.fill('app');
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (less than 300ms)
    await page.waitForTimeout(100);

    // Type fourth character
    await searchInput.fill('appl');
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (less than 300ms)
    await page.waitForTimeout(100);

    // Type fifth character
    await searchInput.fill('apple');
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (more than 300ms)
    await page.waitForTimeout(350);

    // Verify API was called exactly once
    expect(apiCallCount).toBe(1);

    // Verify search results are displayed
    await expect(resultsContainer).toContainText('apple');
    await expect(resultsContainer).toContainText('Apple Inc.');
  });

  test('should not trigger search API if input is cleared before debounce period', async ({ page }) => {
    // Setup API interception
    await page.route('**/api/search?q=*', (route) => {
      route.continue();
    });

    // Get search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Get search button using getByRole
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();

    // Intercept and count API calls
    let apiCallCount = 0;
    await page.route('**/api/search?q=*', (route) => {
      apiCallCount++;
      route.continue();
    });

    // Type first character
    await searchInput.fill('a');
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (less than 300ms)
    await page.waitForTimeout(100);

    // Clear the input
    await searchInput.clear();
    await expect(apiCallCount).toBe(0);

    // Wait for debounce period (more than 300ms)
    await page.waitForTimeout(350);

    // Verify API was never called
    expect(apiCallCount).toBe(0);

    // Verify results container is empty
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
    await expect(resultsContainer).not.toContainText('results');
  });
});
